import type { CoreRow } from "./i18n-core-errors";

/**
 * Páginas de informação (legal.ts): Termos de Uso, Política de Privacidade, Como apagar a conta,
 * Devoluções e reembolsos e as perguntas da Ajuda (HELP_FAQ).
 * Nota: o texto legal em português é o que vale; as traduções servem para ajudar a ler.
 */
export const CORE_LEGAL_ROWS: CoreRow[] = [
  ["Pode contactar-nos através da sua conta (Conta → Ajuda) ou denunciando o conteúdo em causa.", "You can contact us through your account (Account → Help) or by reporting the content concerned.", "您可以通过您的账户（账户 → 帮助）或举报相关内容来联系我们。"],

  // --- Termos de Uso ---
  ["Estas regras valem para o Site e a APP Huambo Online. Ao criar conta ou usar o serviço, aceita estes termos.", "These rules apply to the Huambo Online website and app. By creating an account or using the service, you accept these terms.", "本规则适用于 Huambo Online 网站和应用。创建账户或使用服务即表示您接受这些条款。"],
  ["1. O que é o Huambo Online", "1. What Huambo Online is", "1. Huambo Online 是什么"],
  ["Um lugar para comprar, vender, trocar e arrendar, encontrar profissionais e empresas, e pedir serviços no Huambo e em Angola.", "A place to buy, sell, swap and rent, find professionals and businesses, and request services in Huambo and across Angola.", "一个在万博及安哥拉各地买卖、交换和租赁，寻找专业人士和企业以及申请服务的平台。"],
  ["O Huambo Online liga as pessoas. Os negócios são feitos entre comprador e vendedor (ou cliente e profissional), que são responsáveis pelo que combinam.", "Huambo Online connects people. Deals are made between buyer and seller (or customer and professional), who are responsible for what they agree.", "Huambo Online 连接人与人。交易在买卖双方（或客户与专业人士）之间进行，双方对约定内容负责。"],
  ["2. A sua conta", "2. Your account", "2. 您的账户"],
  ["Deve ter pelo menos 18 anos, ou autorização de quem tem a sua responsabilidade.", "You must be at least 18 years old, or have permission from your legal guardian.", "您必须年满18岁，或获得监护人的许可。"],
  ["Os dados da conta devem ser verdadeiros. Guarde bem a sua palavra-passe: tudo o que for feito na sua conta é da sua responsabilidade.", "Your account details must be true. Keep your password safe: you are responsible for everything done on your account.", "账户信息必须真实。请妥善保管密码：您需对账户中的一切行为负责。"],
  ["Pode apagar a conta quando quiser (veja «Como apagar a minha conta»).", "You can delete your account whenever you want (see «How to delete my account»).", "您可以随时删除账户（参见「如何删除我的账户」）。"],
  ["3. Anúncios, produtos e serviços", "3. Listings, products and services", "3. 信息、商品和服务"],
  ["Só pode anunciar o que é seu ou o que tem autorização para vender, arrendar, trocar ou prestar.", "You may only list what is yours or what you are authorised to sell, rent, swap or provide.", "您只能发布属于您的物品，或您有权出售、出租、交换或提供的物品和服务。"],
  ["O título, o preço, as fotografias e a descrição devem corresponder à verdade. Indique se o preço é fixo, negociável, aberto a propostas, leilão ou troca.", "The title, price, photos and description must be truthful. State whether the price is fixed, negotiable, open to offers, an auction or a swap.", "标题、价格、照片和描述必须真实。请注明价格是固定、可议、接受报价、拍卖还是交换。"],
  ["Garantia de conformidade: ao publicar, declara que o anúncio descreve o artigo com verdade e por completo, incluindo defeitos e o que falta. Se houver omissão ou erro, quem comprou ou arrendou tem direito a troca, devolução com reembolso ou reembolso (todo ou parte). Pode reclamar até 7 dias depois do negócio, em «Devoluções e reembolsos»; o dono responde em 3 dias e, se recusar ou não responder, a administração decide. Quem não cumprir a decisão pode ter a conta suspensa.", "Conformity guarantee: by publishing, you declare that the listing describes the item truthfully and completely, including defects and anything missing. If something is left out or wrong, the buyer or renter is entitled to an exchange, a return with refund, or a refund (full or partial). Claims can be made up to 7 days after the deal, in «Returns and refunds»; the owner replies within 3 days and, if they refuse or don't reply, the administration decides. Anyone who doesn't comply with the decision may have their account suspended.", "符合性保证：发布即表示您声明信息如实、完整地描述了物品，包括缺陷和缺少的部分。如有遗漏或错误，购买或租用者有权换货、退货退款或退款（全部或部分）。可在交易后7天内于「退货和退款」中投诉；物主须在3天内回复，若拒绝或未回复，由管理员裁决。不执行裁决者可能被暂停账户。"],
  ["É proibido anunciar: armas, drogas, medicamentos sem autorização, animais protegidos, produtos roubados ou falsificados, documentos, conteúdos sexuais, e tudo o que a lei angolana proíba.", "It is forbidden to list: weapons, drugs, unauthorised medicines, protected animals, stolen or counterfeit goods, documents, sexual content, and anything prohibited by Angolan law.", "禁止发布：武器、毒品、未经许可的药品、受保护动物、被盗或假冒商品、证件、色情内容，以及安哥拉法律禁止的一切物品。"],
  ["A administração pode esconder ou retirar anúncios, produtos e perfis que não cumpram estas regras, e suspender contas.", "The administration may hide or remove listings, products and profiles that break these rules, and suspend accounts.", "管理员可以隐藏或删除违反这些规则的信息、商品和资料，并暂停账户。"],
  ["4. Propostas, leilões, trocas e encomendas", "4. Offers, auctions, swaps and orders", "4. 报价、拍卖、交换和订单"],
  ["Uma proposta aceite, um lance vencedor ou uma encomenda confirmada é um compromisso entre as duas pessoas. Cumpra o que combinou.", "An accepted offer, a winning bid or a confirmed order is a commitment between the two people. Keep to what you agreed.", "已接受的报价、获胜的出价或已确认的订单是双方之间的承诺。请履行约定。"],
  ["Pode retirar uma proposta enquanto não tiver resposta. Um lance só pode ser retirado com motivo, se faltarem mais de 12 horas para o fim do leilão ou se foi feito há menos de 1 hora; quem retira lances muitas vezes pode ser impedido de licitar.", "You can withdraw an offer while it has no reply. A bid can only be withdrawn with a reason, if there are more than 12 hours until the auction ends or if it was made less than 1 hour ago; people who withdraw bids often may be blocked from bidding.", "在对方回复前，您可以撤回报价。出价只能在说明原因的情况下撤回，且须距拍卖结束超过12小时或出价不足1小时；频繁撤回出价者可能被禁止出价。"],
  ["Nunca pague adiantado a quem não conhece. Prefira encontrar-se num local público, ver o artigo e pagar na entrega.", "Never pay in advance to someone you don't know. Prefer to meet in a public place, see the item and pay on delivery.", "切勿向陌生人预付款。最好在公共场所见面、看货并当面付款。"],
  ["Nas encomendas da Loja, o comprador pode pedir devolução, reembolso ou troca até 14 dias depois da entrega, e o vendedor deve responder. Veja «Devoluções e reembolsos».", "For Shop orders, the buyer can request a return, refund or exchange up to 14 days after delivery, and the seller must reply. See «Returns and refunds».", "对于商店订单，买家可在送达后14天内申请退货、退款或换货，卖家必须回复。参见「退货和退款」。"],
  ["5. Mensalidades e comissões", "5. Monthly fees and commissions", "5. 月费和佣金"],
  ["Os perfis de profissionais e de empresas têm um mês grátis. Depois, pagam uma mensalidade à plataforma: 2 000 Kz por mês para profissionais e 5 000 Kz por mês para empresas (os valores em vigor aparecem em «O meu plano»).", "Professional and business profiles get one free month. After that, they pay the platform a monthly fee: 2 000 Kz per month for professionals and 5 000 Kz per month for businesses (current amounts are shown in «My plan»).", "专业人士和企业资料可享一个月免费。之后需向平台支付月费：专业人士每月2 000 Kz，企业每月5 000 Kz（现行金额见「我的套餐」）。"],
  ["O pagamento é feito por transferência bancária ou Multicaixa Express, com a referência ou o comprovativo, e fica válido quando a administração o confirma.", "Payment is made by bank transfer or Multicaixa Express, with the reference or proof, and becomes valid once the administration confirms it.", "付款通过银行转账或 Multicaixa Express 进行，需提供参考号或付款凭证，经管理员确认后生效。"],
  ["As Lojas (produtos vendidos na Loja sem empresa) seguem o mesmo critério das empresas: um mês grátis e depois 5 000 Kz por mês. Os produtos de uma empresa ficam cobertos pela mensalidade dessa empresa.", "Shops (products sold in the Shop without a business) follow the same rule as businesses: one free month and then 5 000 Kz per month. A business's products are covered by that business's monthly fee.", "商店（不属于企业、在商店中销售的商品）与企业规则相同：一个月免费，之后每月5 000 Kz。企业的商品包含在该企业的月费中。"],
  ["Sem mês grátis nem pagamento em dia, o perfil ou a Loja deixa de aparecer aos clientes, mas não é apagado. Volta a aparecer quando o pagamento é confirmado.", "Without a free month or an up-to-date payment, the profile or Shop stops being shown to customers, but it is not deleted. It reappears when payment is confirmed.", "若无免费月且未按时付款，资料或商店将不再向客户显示，但不会被删除。付款确认后将恢复显示。"],
  ["Anúncios classificados não pagam mensalidade: quando um artigo é vendido (incluindo leilões), o vendedor paga à plataforma uma comissão de 5% do valor da venda, no prazo de 7 dias. O mesmo vale para o arrendamento e o aluguer de bens móveis e imóveis: 5% do valor do arrendamento indicado ao marcar «Arrendado», ou do valor total de um pedido de aluguer aceite. Com comissões em atraso não se podem publicar anúncios novos.", "Classified listings don't pay a monthly fee: when an item is sold (including auctions), the seller pays the platform a commission of 5% of the sale value within 7 days. The same applies to renting and hiring out movable and immovable goods: 5% of the rental value stated when marking «Rented», or of the total value of an accepted hire request. With overdue commissions, new listings can't be published.", "分类信息无需支付月费：物品售出（包括拍卖）时，卖家须在7天内向平台支付成交金额5%的佣金。动产和不动产的出租和租用同样适用：按标记「已出租」时填写的租金或已接受租用申请的总金额收取5%。有逾期佣金时不能发布新信息。"],
  ["Destaques (opcional): o vendedor pode pagar para o anúncio aparecer no topo das listas, com o selo «⭐ Destaque», durante o número de dias indicado (500 Kz por 7 dias, salvo outro valor anunciado). O destaque começa quando a administração confirma o pagamento e termina sozinho no fim do prazo. Não garante a venda.", "Featuring (optional): the seller can pay for the listing to appear at the top of lists, with the «⭐ Featured» badge, for the number of days stated (500 Kz for 7 days, unless another amount is announced). Featuring starts when the administration confirms payment and ends automatically at the end of the period. It does not guarantee a sale.", "推荐（可选）：卖家可付费让信息在列表顶部显示并带有「⭐ 推荐」标识，持续所示天数（7天500 Kz，另有公告除外）。推荐在管理员确认付款后开始，到期自动结束。推荐不保证售出。"],
  ["6. Pagamento protegido", "6. Protected payment", "6. 保障支付"],
  ["Quando estiver disponível, pode escolher o «Pagamento protegido» nas compras da Loja. Paga ao Huambo Online, que guarda o dinheiro e só o entrega ao vendedor depois de o comprador confirmar que recebeu a encomenda.", "When available, you can choose «Protected payment» for Shop purchases. You pay Huambo Online, which holds the money and only releases it to the seller after the buyer confirms they received the order.", "开通后，您可在商店购物时选择「保障支付」。您向 Huambo Online 付款，由其托管款项，待买家确认收到订单后才交给卖家。"],
  ["Se o comprador não confirmar nem reclamar dentro do prazo indicado depois da entrega (3 dias, salvo outro valor anunciado), o dinheiro é entregue ao vendedor. Um pedido de devolução ou reembolso aberto a tempo congela o dinheiro até ser resolvido.", "If the buyer neither confirms nor complains within the stated period after delivery (3 days, unless another period is announced), the money is released to the seller. A return or refund request opened in time freezes the money until it is resolved.", "如果买家在送达后的规定期限内（3天，另有公告除外）既未确认也未投诉，款项将交给卖家。及时提出的退货或退款申请会冻结款项直至解决。"],
  ["Encomendas protegidas que não são pagas dentro do prazo indicado (48 horas, salvo outro valor anunciado) são canceladas. Os reembolsos de dinheiro ainda guardado são feitos pelo Huambo Online, para o IBAN ou o número Multicaixa Express indicado pelo comprador.", "Protected orders not paid within the stated period (48 hours, unless another period is announced) are cancelled. Refunds of money still held are made by Huambo Online, to the IBAN or Multicaixa Express number given by the buyer.", "未在规定期限内（48小时，另有公告除外）付款的保障订单将被取消。仍在托管中的款项由 Huambo Online 退还至买家提供的 IBAN 或 Multicaixa Express 号码。"],
  ["O vendedor recebe as vendas libertadas no seu saldo e pede o levantamento para a sua conta. Os levantamentos são pagos por transferência nos dias anunciados em «O meu saldo». Se houver comissão sobre o pagamento protegido, é mostrada antes de vender e descontada no saldo.", "The seller receives released sales in their balance and requests a withdrawal to their account. Withdrawals are paid by transfer on the days announced in «My balance». If there is a commission on protected payment, it is shown before selling and deducted from the balance.", "卖家已释放的销售款进入其余额，可申请提现到自己的账户。提现在「我的余额」中公布的日期通过转账支付。如保障支付有佣金，会在出售前显示并从余额中扣除。"],
  ["O Huambo Online atua apenas como intermediário tecnológico e de pagamento: não é o vendedor dos produtos nem responde pela sua qualidade, mas segue as regras de devolução descritas em «Devoluções e reembolsos».", "Huambo Online acts only as a technology and payment intermediary: it is not the seller of the products and is not responsible for their quality, but it follows the return rules described in «Returns and refunds».", "Huambo Online 仅作为技术和支付中介：并非商品的卖家，也不对商品质量负责，但遵循「退货和退款」中的退货规则。"],
  ["7. Avaliações e denúncias", "7. Reviews and reports", "7. 评价和举报"],
  ["Só quem fez negócio pode avaliar. As avaliações devem ser honestas e sem insultos.", "Only those who did business can leave a review. Reviews must be honest and free of insults.", "只有完成交易的人才能评价。评价必须诚实，不得辱骂。"],
  ["Se vir algo errado, use «Denunciar». A administração analisa as denúncias e pode retirar conteúdos.", "If you see something wrong, use «Report». The administration reviews reports and may remove content.", "如发现问题，请使用「举报」。管理员会审核举报并可能删除内容。"],
  ["8. Verificação de perfis", "8. Profile verification", "8. 资料认证"],
  ["O selo «Verificado» quer dizer que a administração viu um documento. Não é uma garantia sobre a pessoa nem sobre o negócio: continue a ter cuidado.", "The «Verified» badge means the administration has seen a document. It is not a guarantee about the person or the deal: keep being careful.", "「已认证」标识表示管理员已查看过证件。这并不是对个人或交易的保证：请继续保持谨慎。"],
  ["9. Responsabilidade", "9. Liability", "9. 责任"],
  ["O Huambo Online faz o possível para manter o serviço a funcionar e seguro, mas não garante que esteja sempre disponível nem responde pelos negócios feitos entre utilizadores.", "Huambo Online does its best to keep the service running and secure, but does not guarantee it will always be available and is not responsible for deals made between users.", "Huambo Online 尽力保持服务正常运行和安全，但不保证服务始终可用，也不对用户之间的交易负责。"],
  ["Estes termos podem mudar. Quando mudarem, a data no topo é atualizada.", "These terms may change. When they do, the date at the top is updated.", "本条款可能会变更。变更时，顶部的日期会更新。"],
  ["10. Contacto", "10. Contact", "10. 联系方式"],

  // --- Política de Privacidade ---
  ["Explicamos que dados guardamos, para quê e quem os pode ver. Seguimos a Lei de Protecção de Dados Pessoais de Angola (Lei n.º 22/11).", "We explain what data we keep, what for and who can see it. We follow Angola's Personal Data Protection Law (Law no. 22/11).", "我们说明保存哪些数据、用途以及谁可以查看。我们遵守安哥拉《个人数据保护法》（第22/11号法律）。"],
  ["1. Que dados guardamos", "1. What data we keep", "1. 我们保存哪些数据"],
  ["Conta: nome, e-mail, telefone (se o indicar), fotografia de perfil, município.", "Account: name, email, phone (if you provide it), profile photo, municipality.", "账户：姓名、电子邮箱、电话（如您提供）、头像、市镇。"],
  ["O que publica: anúncios, produtos, fotografias, vídeos, preços, propostas, avaliações e respostas.", "What you post: listings, products, photos, videos, prices, offers, reviews and replies.", "您发布的内容：信息、商品、照片、视频、价格、报价、评价和回复。"],
  ["Conversas: as mensagens que troca com outras pessoas.", "Conversations: the messages you exchange with other people.", "对话：您与他人互发的消息。"],
  ["Negócios: encomendas, pedidos de serviço, alugueres, entregas e o histórico de cada um.", "Deals: orders, service requests, hires, deliveries and the history of each.", "交易：订单、服务申请、租用、配送及各自的历史记录。"],
  ["Verificação (só se a pedir): a fotografia do documento (BI, alvará ou NIF).", "Verification (only if you request it): the photo of the document (ID card, licence or tax number).", "认证（仅在您申请时）：证件照片（身份证、营业执照或税号）。"],
  ["No telemóvel: guardamos no próprio aparelho os anúncios vistos e a última pesquisa, para poder ver sem internet.", "On your phone: we store the listings you viewed and your last search on the device itself, so you can see them without internet.", "在手机上：我们在设备本地保存您浏览过的信息和最近一次搜索，以便无网络时也能查看。"],
  ["2. Para que usamos os dados", "2. What we use the data for", "2. 我们如何使用数据"],
  ["Para o serviço funcionar: mostrar anúncios, ligar compradores e vendedores, enviar notificações e mensagens, calcular avaliações e números do perfil.", "To run the service: showing listings, connecting buyers and sellers, sending notifications and messages, calculating ratings and profile figures.", "用于运行服务：展示信息、连接买家和卖家、发送通知和消息、计算评分和资料数据。"],
  ["Para segurança: analisar denúncias, verificar perfis e impedir abusos.", "For security: reviewing reports, verifying profiles and preventing abuse.", "用于安全：审核举报、认证资料并防止滥用。"],
  ["Não vendemos os seus dados a ninguém e não mostramos publicidade com base neles.", "We don't sell your data to anyone and we don't show advertising based on it.", "我们不会向任何人出售您的数据，也不会基于这些数据投放广告。"],
  ["3. O que é público", "3. What is public", "3. 哪些内容是公开的"],
  ["Os anúncios publicados, produtos, perfis de profissionais e empresas, o seu nome, a fotografia de perfil, as avaliações e os números do perfil (vendas, serviços prestados).", "Published listings, products, professional and business profiles, your name, profile photo, reviews and profile figures (sales, services provided).", "已发布的信息、商品、专业人士和企业资料、您的姓名、头像、评价和资料数据（销售、已提供服务）。"],
  ["O seu e-mail, telefone, WhatsApp e localização (morada, indicações e ponto no mapa) não são mostrados a outros utilizadores. Só a equipa do Huambo Online (administração e moderadores) os vê. Os outros utilizadores falam consigo pelas Mensagens.", "Your email, phone, WhatsApp and location (address, directions and map point) are not shown to other users. Only the Huambo Online team (administrators and moderators) can see them. Other users contact you through Messages.", "您的电子邮箱、电话、WhatsApp 和位置（地址、路线说明和地图位置）不会向其他用户显示。只有 Huambo Online 团队（管理员和版主）可以看到。其他用户通过站内消息与您联系。"],
  ["Empresas, postos de combustível, hotéis, restaurantes e eventos mostram só a localização (morada e mapa), para poderem ser encontrados. O telefone e o WhatsApp deles também ficam só para a equipa. Pode apagar o seu número de WhatsApp quando quiser.", "Businesses, fuel stations, hotels, restaurants and events only show their location (address and map), so they can be found. Their phone and WhatsApp are also kept only for the team. You can delete your WhatsApp number at any time.", "企业、加油站、酒店、餐厅和活动只显示位置（地址和地图），以便被人找到。它们的电话和 WhatsApp 也仅供团队查看。您可以随时删除您的 WhatsApp 号码。"],
  ["4. O que é privado", "4. What is private", "4. 哪些内容是私密的"],
  ["As mensagens passam sempre pela equipa do Huambo Online (administração e moderadores), que as lê e as reencaminha à outra parte: os utilizadores não falam diretamente entre si. Encomendas, reservas, bilhetes, propostas, alugueres e pedidos de serviço também chegam primeiro à equipa, que os reencaminha a quem os vai tratar. O seu telefone e a sua morada só são partilhados quando forem precisos para a entrega ou o serviço.", "Messages always go through the Huambo Online team (administrators and moderators), who read them and forward them to the other party: users do not talk to each other directly. Orders, bookings, tickets, offers, rentals and service requests also go to the team first, who forward them to whoever will handle them. Your phone and address are only shared when needed for delivery or the service.", "所有消息都会先经过 Huambo Online 团队（管理员和版主），由团队阅读后转发给对方：用户之间不会直接交流。订单、预订、门票、报价、租赁和服务请求也会先到达团队，由团队转发给处理方。只有在配送或服务需要时，才会共享您的电话和地址。"],
  ["Os documentos de verificação ficam num espaço privado: só o próprio e a administração os podem abrir, através de uma ligação temporária.", "Verification documents are kept in a private space: only you and the administration can open them, through a temporary link.", "认证证件保存在私密空间：只有您本人和管理员可以通过临时链接打开。"],
  ["5. Onde ficam os dados e quem nos ajuda", "5. Where the data is kept and who helps us", "5. 数据存放在哪里以及谁为我们提供帮助"],
  ["A base de dados e os ficheiros estão no Supabase, em servidores na União Europeia (Alemanha, Frankfurt).", "The database and files are on Supabase, on servers in the European Union (Germany, Frankfurt).", "数据库和文件存放在 Supabase，服务器位于欧盟（德国法兰克福）。"],
  ["O Site está alojado na Vercel. A APP é feita com Expo.", "The website is hosted on Vercel. The app is built with Expo.", "网站托管在 Vercel。应用使用 Expo 开发。"],
  ["Pesquisa por fotografia (quando estiver ativa): a fotografia é enviada ao Claude (Anthropic) para dizer o que é o artigo, e não é guardada por nós.", "Photo search (when active): the photo is sent to Claude (Anthropic) to identify the item, and is not stored by us.", "拍照搜索（开通后）：照片会发送给 Claude（Anthropic）以识别物品，我们不会保存照片。"],
  ["6. Quanto tempo guardamos", "6. How long we keep data", "6. 数据保存多久"],
  ["Enquanto a conta existir. Os vídeos de anúncios fechados ou vendidos são apagados automaticamente depois de 7 dias, e os de produtos escondidos depois de 30 dias.", "For as long as the account exists. Videos of closed or sold listings are deleted automatically after 7 days, and those of hidden products after 30 days.", "在账户存在期间保存。已关闭或已售信息的视频会在7天后自动删除，已隐藏商品的视频会在30天后删除。"],
  ["Quando apaga a conta, os seus dados são apagados. Algumas cópias de segurança do fornecedor podem durar mais algum tempo até serem substituídas.", "When you delete your account, your data is deleted. Some of the provider's backups may last a little longer until they are replaced.", "删除账户后，您的数据会被删除。服务商的部分备份可能会多保留一段时间，直至被替换。"],
  ["7. Os seus direitos", "7. Your rights", "7. 您的权利"],
  ["Pode ver e corrigir os seus dados em «A sua conta», e apagar anúncios, produtos e a própria conta quando quiser.", "You can view and correct your data in «Your account», and delete listings, products and the account itself whenever you want.", "您可以在「您的账户」中查看和更正数据，并随时删除信息、商品和账户本身。"],
  ["Pode pedir informação sobre os seus dados ou opor-se a um tratamento. Se achar que os seus direitos não foram respeitados, pode queixar-se à Agência de Protecção de Dados (APD) de Angola.", "You can ask for information about your data or object to its processing. If you think your rights have not been respected, you can complain to Angola's Data Protection Agency (APD).", "您可以申请了解您的数据或反对某项数据处理。如认为您的权利未受尊重，可向安哥拉数据保护局（APD）投诉。"],
  ["8. Contacto", "8. Contact", "8. 联系方式"],

  // --- Como apagar a minha conta ---
  ["Como apagar a minha conta", "How to delete my account", "如何删除我的账户"],
  ["Pode apagar a sua conta do Huambo Online a qualquer momento, no Site ou na APP.", "You can delete your Huambo Online account at any time, on the website or in the app.", "您可以随时在网站或应用中删除您的 Huambo Online 账户。"],
  ["Passos", "Steps", "步骤"],
  ["1. Entre na sua conta (Site ou APP).", "1. Sign in to your account (website or app).", "1. 登录您的账户（网站或应用）。"],
  ["2. Abra «A sua conta».", "2. Open «Your account».", "2. 打开「您的账户」。"],
  ["3. No fim da página, em «Eliminar conta», escreva ELIMINAR e confirme.", "3. At the bottom of the page, under «Delete account», type ELIMINAR and confirm.", "3. 在页面底部的「删除账户」中输入 ELIMINAR 并确认。"],
  ["O que é apagado", "What is deleted", "哪些内容会被删除"],
  ["A conta, o perfil, os anúncios, produtos, guardados, pesquisas guardadas, notificações e os dados ligados à conta.", "The account, profile, listings, products, saved items, saved searches, notifications and the data linked to the account.", "账户、资料、信息、商品、收藏、已保存的搜索、通知以及与账户关联的数据。"],
  ["As avaliações que deixou a outras pessoas e as mensagens já enviadas podem ser apagadas ou ficar sem o seu nome.", "Reviews you left for other people and messages already sent may be deleted or remain without your name.", "您给他人留下的评价和已发送的消息可能会被删除，或保留但不显示您的姓名。"],
  ["Não consegue entrar?", "Can't sign in?", "无法登录？"],
  ["Use «Esqueci-me da palavra-passe» na página de entrada para recuperar o acesso e depois apague a conta.", "Use «I forgot my password» on the sign-in page to recover access and then delete the account.", "请在登录页面使用「忘记密码」恢复访问，然后删除账户。"],

  // --- Devoluções e reembolsos ---
  ["Como pedir a devolução, o reembolso ou a troca de uma encomenda feita na Loja do Huambo Online, e o que acontece em cada passo.", "How to request a return, refund or exchange for an order placed in the Huambo Online Shop, and what happens at each step.", "如何为在 Huambo Online 商店下的订单申请退货、退款或换货，以及每一步会发生什么。"],
  ["Anúncios: o artigo tem de corresponder ao anúncio", "Listings: the item must match the listing", "信息：物品必须与信息相符"],
  ["Quem publica um anúncio declara que a descrição, as fotografias e o preço correspondem ao artigo, incluindo defeitos.", "Whoever publishes a listing declares that the description, photos and price match the item, including defects.", "发布信息者声明描述、照片和价格与物品相符，包括缺陷。"],
  ["Se comprou ou arrendou e o artigo tem um defeito escondido, é diferente da descrição, é outro artigo ou faltam peças, abra o anúncio e carregue em «O artigo não corresponde ao anúncio» (até 7 dias depois do negócio).", "If you bought or rented and the item has a hidden defect, differs from the description, is a different item or has missing parts, open the listing and tap «The item doesn't match the listing» (up to 7 days after the deal).", "如果您购买或租用的物品有隐藏缺陷、与描述不符、是另一件物品或缺少零件，请打开该信息并点击「物品与信息不符」（交易后7天内）。"],
  ["Escolha o que quer: troca, devolução e reembolso, ou reembolso. O dono tem 3 dias para responder; se recusar ou não responder, peça à administração para decidir. As reclamações aparecem nesta página.", "Choose what you want: exchange, return and refund, or refund. The owner has 3 days to reply; if they refuse or don't reply, ask the administration to decide. Claims appear on this page.", "请选择您的诉求：换货、退货并退款或退款。物主有3天时间回复；若拒绝或未回复，请管理员裁决。投诉会显示在此页面。"],
  ["1. Quando posso pedir", "1. When I can request", "1. 何时可以申请"],
  ["Numa encomenda da Loja que já pagou ou que já recebeu, até 14 dias depois da entrega.", "For a Shop order you've already paid for or received, up to 14 days after delivery.", "对于已付款或已收到的商店订单，可在送达后14天内申请。"],
  ["Motivos: não recebeu, chegou estragado ou partido, é diferente do anúncio, artigo errado (modelo, tamanho, cor) ou faltam artigos.", "Reasons: not received, arrived damaged or broken, not as described in the listing, wrong item (model, size, colour) or items missing.", "原因：未收到、到货时已损坏或破碎、与信息描述不符、物品错误（型号、尺码、颜色）或缺少物品。"],
  ["Se a encomenda ainda está «Pendente», não precisa de pedido: carregue em «Cancelar».", "If the order is still «Pending», you don't need a request: tap «Cancel».", "如果订单仍为「待处理」，无需申请：直接点击「取消」。"],
  ["2. O que posso pedir", "2. What I can request", "2. 可以申请什么"],
  ["Reembolso: o vendedor devolve-lhe o dinheiro (todo ou parte).", "Refund: the seller gives you your money back (all or part).", "退款：卖家向您退还款项（全部或部分）。"],
  ["Devolução e reembolso: devolve o artigo ao vendedor e ele devolve-lhe o dinheiro.", "Return and refund: you return the item to the seller and they give you your money back.", "退货并退款：您将物品退回卖家，卖家向您退款。"],
  ["Troca: o vendedor envia-lhe outro artigo igual, em bom estado.", "Exchange: the seller sends you another identical item in good condition.", "换货：卖家给您寄一件完好的相同物品。"],
  ["3. Como pedir", "3. How to request", "3. 如何申请"],
  ["Abra «Encomendas», escolha a encomenda e carregue em «Pedir devolução ou reembolso».", "Open «Orders», choose the order and tap «Request return or refund».", "打开「订单」，选择该订单并点击「申请退货或退款」。"],
  ["Escolha o motivo, explique o que aconteceu e junte até 4 fotografias. As fotografias ficam privadas: só o vendedor e a administração as veem.", "Choose the reason, explain what happened and add up to 4 photos. The photos stay private: only the seller and the administration see them.", "选择原因，说明发生了什么，并最多添加4张照片。照片是私密的：只有卖家和管理员可以查看。"],
  ["Acompanhe tudo em «Devoluções e reembolsos». Cada passo envia uma notificação à outra pessoa.", "Follow everything in «Returns and refunds». Each step sends a notification to the other person.", "在「退货和退款」中跟进全部进展。每一步都会通知对方。"],
  ["4. O que o vendedor faz", "4. What the seller does", "4. 卖家要做什么"],
  ["Aceita o pedido ou recusa-o explicando o motivo.", "Accepts the request or declines it, explaining why.", "接受申请，或说明理由后拒绝。"],
  ["Se aceitar uma devolução, combinem pelas mensagens onde entregar o artigo. Quando o receber, confirma e devolve o dinheiro.", "If they accept a return, agree through messages where to hand over the item. When they receive it, they confirm and refund the money.", "如果接受退货，双方通过消息约定交还物品的地点。卖家收到后确认并退款。"],
  ["Quando devolver o dinheiro, carrega em «Já devolvi o dinheiro» e o comprador confirma que recebeu.", "When they refund the money, they tap «I've refunded the money» and the buyer confirms receipt.", "退款后，卖家点击「我已退款」，买家确认收到。"],
  ["5. Se não se entenderem", "5. If you can't agree", "5. 如果双方无法达成一致"],
  ["Se o vendedor recusar, pode chamar a administração logo. Se alguém não responder em 3 dias, qualquer um dos dois pode chamar a administração.", "If the seller declines, you can call in the administration straight away. If someone doesn't reply within 3 days, either of you can call in the administration.", "如果卖家拒绝，您可以立即请管理员介入。如果有一方3天内未回复，任何一方都可以请管理员介入。"],
  ["A administração vê o pedido, as mensagens e as fotografias, e decide: reembolso (todo ou parte), devolução, troca ou recusa. A decisão fica registada.", "The administration looks at the request, messages and photos, and decides: refund (full or partial), return, exchange or rejection. The decision is recorded.", "管理员会查看申请、消息和照片，并作出裁决：退款（全部或部分）、退货、换货或驳回。裁决会被记录。"],
  ["Quem não cumprir uma decisão pode ter a conta suspensa.", "Anyone who doesn't comply with a decision may have their account suspended.", "不执行裁决者可能被暂停账户。"],
  ["6. Encomenda paga e cancelada", "6. Order paid and cancelled", "6. 已付款但被取消的订单"],
  ["Se a encomenda já estava paga e foi cancelada, o pedido de reembolso abre sozinho: o vendedor tem de devolver o dinheiro todo.", "If the order was already paid and was cancelled, the refund request opens automatically: the seller must refund all the money.", "如果订单已付款后被取消，系统会自动发起退款申请：卖家必须全额退款。"],
  ["Com pagamento protegido, quem devolve o dinheiro ainda guardado é o Huambo Online: indique no pedido o seu IBAN ou o número Multicaixa Express.", "With protected payment, Huambo Online refunds any money still held: enter your IBAN or Multicaixa Express number in the request.", "使用保障支付时，仍在托管中的款项由 Huambo Online 退还：请在申请中填写您的 IBAN 或 Multicaixa Express 号码。"],
  ["7. Como chega o dinheiro", "7. How the money arrives", "7. 款项如何到账"],
  ["Nas compras pagas ao vendedor (na entrega, transferência ou Multicaixa Express), o Huambo Online não guarda o dinheiro: o reembolso é feito pelo vendedor, pelo mesmo meio do pagamento, salvo outro acordo entre os dois.", "For purchases paid to the seller (on delivery, by transfer or Multicaixa Express), Huambo Online doesn't hold the money: the refund is made by the seller, by the same payment method, unless the two of you agree otherwise.", "对于直接付给卖家的购买（货到付款、转账或 Multicaixa Express），Huambo Online 不托管款项：退款由卖家以原付款方式退还，双方另有约定除外。"],
  ["Nas compras com pagamento protegido, o dinheiro fica guardado pelo Huambo Online até confirmar a receção. Enquanto estiver guardado, o reembolso é feito pelo Huambo Online. Depois de entregue ao vendedor, é o vendedor que devolve.", "For purchases with protected payment, Huambo Online holds the money until receipt is confirmed. While it is held, the refund is made by Huambo Online. Once released to the seller, it is the seller who refunds.", "使用保障支付的购买，款项由 Huambo Online 托管直至确认收货。托管期间由 Huambo Online 退款。款项交给卖家后，由卖家退款。"],
  ["Guarde os comprovativos de pagamento e de reembolso: podem ser pedidos pela administração.", "Keep proofs of payment and refund: the administration may ask for them.", "请保留付款和退款凭证：管理员可能会要求提供。"],
  ["8. Negócios fora da Loja", "8. Deals outside the Shop", "8. 商店以外的交易"],
  ["Nos anúncios classificados (venda, troca, arrendamento) o negócio é feito diretamente entre as pessoas, mas vale a garantia de conformidade: se o artigo não corresponder ao anúncio, use «O artigo não corresponde ao anúncio» na página do anúncio (veja acima). Para outros problemas, use «Denunciar» e a administração analisa.", "In classified listings (sale, swap, rental) the deal is made directly between people, but the conformity guarantee applies: if the item doesn't match the listing, use «The item doesn't match the listing» on the listing page (see above). For other problems, use «Report» and the administration will review it.", "在分类信息中（出售、交换、出租），交易直接在双方之间进行，但适用符合性保证：如果物品与信息不符，请在信息页面使用「物品与信息不符」（见上文）。其他问题请使用「举报」，由管理员审核。"],
  ["9. Contacto", "9. Contact", "9. 联系方式"],

  // --- Ajuda (HELP_FAQ) ---
  ["Como publico um anúncio?", "How do I post a listing?", "如何发布信息？"],
  ["Carregue em «Vender» ou «Publicar anúncio», escolha o tipo e a finalidade, diga como quer vender (preço fixo, negociável, propostas, leilão ou troca), junte fotografias e publique.", "Tap «Sell» or «Post listing», choose the type and purpose, say how you want to sell (fixed price, negotiable, offers, auction or swap), add photos and publish.", "点击「出售」或「发布信息」，选择类型和用途，说明出售方式（固定价格、可议价、接受报价、拍卖或交换），添加照片后发布。"],
  ["O que é «Preço fixo», «Negociável» e «Aberto a propostas»?", "What are «Fixed price», «Negotiable» and «Open to offers»?", "什么是「固定价格」、「可议价」和「接受报价」？"],
  ["Preço fixo: quem quiser compra pelo preço indicado («Quero comprar»). Negociável: o comprador pode fazer uma proposta mais baixa. Aberto a propostas: o preço é só uma referência e os compradores dizem quanto pagam.", "Fixed price: anyone who wants it buys at the stated price («I want to buy»). Negotiable: the buyer can make a lower offer. Open to offers: the price is only a guide and buyers say how much they'll pay.", "固定价格：想买的人按标价购买（「我要买」）。可议价：买家可以提出更低的报价。接受报价：价格仅供参考，由买家出价。"],
  ["Como funcionam as trocas?", "How do swaps work?", "交换如何进行？"],
  ["Escolha «Só troca» ou marque «Também aceito troca» e diga o que aceita. Quem estiver interessado propõe um artigo (e pode juntar dinheiro). Veja todas em «Trocas».", "Choose «Swap only» or tick «I also accept swaps» and say what you'll accept. Anyone interested offers an item (and can add money). See them all in «Swaps».", "选择「仅限交换」或勾选「也接受交换」，并说明您接受什么。有兴趣的人会提出一件物品（也可以补差价）。在「以物易物」中查看全部。"],
  ["Como faço uma proposta?", "How do I make an offer?", "如何报价？"],
  ["No anúncio, carregue em «Fazer proposta», indique o valor e/ou o que oferece em troca. O vendedor aceita ou recusa e recebe uma notificação; acompanhe em «As minhas propostas».", "On the listing, tap «Make offer», enter the amount and/or what you're offering in exchange. The seller accepts or declines and gets a notification; follow it in «My offers».", "在信息页面点击「报价」，填写金额和/或您用于交换的物品。卖家会收到通知并选择接受或拒绝；可在「我的报价」中跟进。"],
  ["Como retiro uma proposta?", "How do I withdraw an offer?", "如何撤回报价？"],
  ["Em «As minhas propostas», carregue em «Retirar proposta». Só é possível enquanto o vendedor ainda não respondeu; depois de aceite, combine com ele pelas mensagens.", "In «My offers», tap «Withdraw offer». This is only possible while the seller hasn't replied yet; once accepted, sort it out with them through messages.", "在「我的报价」中点击「撤回报价」。只能在卖家尚未回复时撤回；报价被接受后，请通过消息与卖家协商。"],
  ["Como funcionam os leilões?", "How do auctions work?", "拍卖如何进行？"],
  ["Como no eBay: escreva o MÁXIMO que está disposto a pagar. O Huambo Online licita por si só o necessário para ficar à frente, até esse máximo, que ninguém vê. Se outra pessoa oferecer mais do que o seu máximo, recebe um aviso e pode subir. Em caso de empate ganha quem licitou primeiro. Quem ganha paga o preço final, que muitas vezes é menor do que o seu máximo. Alguns leilões têm «Comprar já»: pode comprar logo por esse preço, até alguém licitar. Acompanhe tudo em «As minhas licitações»; recebe um aviso quando faltar menos de 1 hora.", "Like on eBay: enter the MAXIMUM you're willing to pay. Huambo Online bids for you only as much as needed to stay ahead, up to that maximum, which nobody sees. If someone else offers more than your maximum, you get a notice and can raise it. In a tie, whoever bid first wins. The winner pays the final price, which is often lower than their maximum. Some auctions have «Buy now»: you can buy straight away at that price, until someone bids. Follow everything in «My bids»; you get a notice when less than 1 hour is left.", "与 eBay 类似：输入您愿意支付的最高价。Huambo Online 会代您按需出价以保持领先，直至该最高价，且他人看不到。如果有人出价超过您的最高价，您会收到通知并可以加价。出价相同时，先出价者获胜。获胜者支付最终成交价，通常低于其最高价。部分拍卖设有「一口价」：在有人出价前可以直接按该价格购买。在「我的出价」中跟进全部进展；剩余不到1小时时会通知您。"],
  ["Como cancelo um lance num leilão?", "How do I cancel a bid in an auction?", "如何取消拍卖中的出价？"],
  ["No anúncio do leilão, abra «Ver lances» e carregue em «Retirar o meu lance», escolhendo o motivo. Pode fazê-lo se faltarem mais de 12 horas para o fim, ou se o lance foi feito há menos de 1 hora. No máximo 3 vezes em 30 dias. O vendedor também pode cancelar os lances de uma pessoa, explicando porquê.", "On the auction listing, open «See bids» and tap «Withdraw my bid», choosing the reason. You can do this if there are more than 12 hours until the end, or if the bid was made less than 1 hour ago. At most 3 times in 30 days. The seller can also cancel a person's bids, explaining why.", "在拍卖信息中打开「查看出价」，点击「撤回我的出价」并选择原因。距结束超过12小时或出价不足1小时时可以撤回。30天内最多3次。卖家也可以在说明理由后取消某人的出价。"],
  ["O que é o número do anúncio (ex.: A-1001)?", "What is the listing number (e.g. A-1001)?", "什么是信息编号（例如：A-1001）？"],
  ["Cada anúncio (A-…), produto (P-…) e encomenda (E-…) tem um número curto, que aparece na página. Use-o para falar com o vendedor ou com a administração, ou escreva-o na pesquisa para abrir o artigo diretamente.", "Every listing (A-…), product (P-…) and order (E-…) has a short number shown on its page. Use it when talking to the seller or the administration, or type it into search to open the item directly.", "每条信息（A-…）、商品（P-…）和订单（E-…）都有一个显示在页面上的短编号。与卖家或管理员沟通时可使用该编号，也可在搜索中输入以直接打开。"],
  ["Como mostro os meus trabalhos (portfólio)?", "How do I show my work (portfolio)?", "如何展示我的作品（作品集）？"],
  ["Profissionais: em «A sua conta» → «Perfil profissional» → «Portfólio», carregue em «Juntar trabalho», dê um título e junte até 8 fotografias. Empresas: em «As minhas empresas» → «Logótipo e portfólio». Os trabalhos aparecem na sua página pública, em «Trabalhos realizados», e pode mudar a ordem.", "Professionals: in «Your account» → «Professional profile» → «Portfolio», tap «Add work», give it a title and add up to 8 photos. Businesses: in «My businesses» → «Logo and portfolio». The works appear on your public page under «Completed work», and you can change the order.", "专业人士：在「您的账户」→「专业人士资料」→「作品集」中点击「添加作品」，填写标题并最多添加8张照片。企业：在「我的企业」→「标志和作品集」中操作。作品会显示在您的公开页面「已完成作品」中，并可调整顺序。"],
  ["Quanto custa ter perfil de profissional ou de empresa?", "How much does a professional or business profile cost?", "专业人士或企业资料收费多少？"],
  ["O primeiro mês é grátis. Depois, os profissionais pagam 2 000 Kz por mês e as empresas 5 000 Kz por mês. Pague em «A sua conta» → «O meu plano», com a referência ou o comprovativo da transferência ou do Multicaixa Express. Recebe avisos 7 dias e 1 dia antes do fim. Sem pagamento, o perfil deixa de aparecer aos clientes até pagar.", "The first month is free. After that, professionals pay 2 000 Kz per month and businesses 5 000 Kz per month. Pay in «Your account» → «My plan», with the reference or proof of the transfer or Multicaixa Express payment. You get reminders 7 days and 1 day before the end. Without payment, the profile stops being shown to customers until you pay.", "第一个月免费。之后专业人士每月2 000 Kz，企业每月5 000 Kz。请在「您的账户」→「我的套餐」中付款，并提供转账或 Multicaixa Express 的参考号或凭证。到期前7天和1天会收到提醒。未付款时，资料将不再向客户显示，直至付款。"],
  ["Quanto custa vender na Loja e nos anúncios?", "How much does it cost to sell in the Shop and in listings?", "在商店和信息中出售收费多少？"],
  ["Loja: o primeiro mês é grátis, depois 5 000 Kz por mês (se os produtos forem de uma empresa, basta a mensalidade da empresa). Anúncios: publicar é grátis; quando vende, arrenda ou aluga, paga uma comissão de 5% do valor em 7 dias, em «A sua conta» → «Comissões». Ao marcar «Vendido» ou «Arrendado» indica o valor e vê logo a comissão; num pedido de aluguer, a comissão é sobre o valor total aceite.", "Shop: the first month is free, then 5 000 Kz per month (if the products belong to a business, the business's monthly fee is enough). Listings: posting is free; when you sell, rent out or hire out, you pay a 5% commission on the amount within 7 days, in «Your account» → «Commissions». When marking «Sold» or «Rented» you enter the amount and see the commission straight away; for a hire request, the commission is on the total accepted amount.", "商店：第一个月免费，之后每月5 000 Kz（如商品属于企业，只需支付企业月费）。信息：发布免费；售出、出租或租出时，须在7天内于「您的账户」→「佣金」中支付金额5%的佣金。标记「已售出」或「已出租」时填写金额即可立即看到佣金；租用申请的佣金按已接受的总金额计算。"],
  ["Como ponho o meu anúncio em destaque?", "How do I feature my listing?", "如何推荐我的信息？"],
  ["Em «Os meus anúncios», no anúncio publicado, carregue em «⭐ Destacar». Pague o valor indicado (500 Kz por 7 dias) por transferência ou Multicaixa Express e escreva a referência ou junte o comprovativo. Quando a administração confirmar, o anúncio aparece no topo das listas com o selo «⭐ Destaque». Pode prolongar antes de terminar.", "In «My listings», on the published listing, tap «⭐ Feature». Pay the amount shown (500 Kz for 7 days) by transfer or Multicaixa Express and enter the reference or attach the proof. When the administration confirms, the listing appears at the top of lists with the «⭐ Featured» badge. You can extend it before it ends.", "在「我的信息」中，于已发布的信息上点击「⭐ 推荐」。通过转账或 Multicaixa Express 支付所示金额（7天500 Kz），并填写参考号或附上凭证。管理员确认后，信息会带「⭐ 推荐」标识显示在列表顶部。到期前可以续期。"],
  ["Como sigo um profissional, uma empresa ou uma loja?", "How do I follow a professional, a business or a shop?", "如何关注专业人士、企业或商店？"],
  ["Na página do profissional, da empresa ou do vendedor, carregue em «➕ Seguir». Recebe um aviso quando publicar um anúncio, um produto ou um trabalho novo (no máximo um aviso por hora de cada um). Veja quem segue em «A sua conta» → «A seguir»; para deixar de seguir, carregue em «✔ A seguir».", "On the professional's, business's or seller's page, tap «➕ Follow». You get a notice when they post a new listing, product or work (at most one notice per hour from each). See who you follow in «Your account» → «Following»; to unfollow, tap «✔ Following».", "在专业人士、企业或卖家的页面点击「➕ 关注」。对方发布新信息、商品或作品时您会收到通知（每个对象每小时最多一条）。在「您的账户」→「已关注」中查看关注列表；如需取消关注，请点击「✔ 已关注」。"],
  ["Como vendo produtos do campo (milho, batata, gado…)?", "How do I sell farm products (maize, potatoes, livestock…)?", "如何出售农产品（玉米、土豆、牲畜…）？"],
  ["Em «Vender», escolha o tipo «Artigo» ou «Outro» e ligue «🌾 Produto do campo». Diga o tipo (cereais, tubérculos, gado…), a unidade de venda (kg, saco de 50 kg, tonelada, cabeça…), a quantidade e, se ainda não colheu, a data «disponível a partir de». O preço aparece por unidade (ex.: 12 000 Kz / saco 50 kg) e o anúncio entra na secção «🌾 Agricultura e campo».", "In «Sell», choose the type «Item» or «Other» and switch on «🌾 Farm product». Say the type (cereals, tubers, livestock…), the sales unit (kg, 50 kg bag, tonne, head…), the quantity and, if you haven't harvested yet, the «available from» date. The price is shown per unit (e.g. 12 000 Kz / 50 kg bag) and the listing goes into the «🌾 Farming» section.", "在「出售」中选择「物品」或「其他」类型，并打开「🌾 农产品」。填写类型（谷物、块茎类、牲畜…）、销售单位（公斤、50公斤袋、吨、头…）、数量，如尚未收获，请填写「供货起始日期」。价格按单位显示（例如：12 000 Kz / 50公斤袋），信息将进入「🌾 农业」栏目。"],
  ["Como peço um serviço a um profissional?", "How do I request a service from a professional?", "如何向专业人士申请服务？"],
  ["Abra a página do profissional ou empresa e use «Pedir serviço». Quando o serviço terminar, confirme e avalie — a avaliação fica marcada «Serviço confirmado».", "Open the professional's or business's page and use «Request service». When the service is finished, confirm and leave a review — the review is marked «Service confirmed».", "打开专业人士或企业的页面并使用「申请服务」。服务完成后请确认并评价——评价会标记为「服务已确认」。"],
  ["Como avalio um vendedor ou comprador?", "How do I review a seller or buyer?", "如何评价卖家或买家？"],
  ["Depois de uma encomenda concluída, ou quando o anúncio é marcado como vendido com a pessoa certa, aparece em «Avaliações» para avaliar.", "After a completed order, or when the listing is marked as sold to the right person, it appears in «Reviews» for you to rate.", "订单完成后，或信息被标记为已售给对应的人后，会出现在「评价」中供您评价。"],
  ["Como fico com o selo «Verificado»?", "How do I get the «Verified» badge?", "如何获得「已认证」标识？"],
  ["Em «A sua conta», abra «Verificar perfil» e envie a fotografia do BI (ou do alvará/NIF da empresa). O documento fica privado; a administração responde por notificação.", "In «Your account», open «Verify profile» and send a photo of your ID card (or the business's licence/tax number). The document stays private; the administration replies by notification.", "在「您的账户」中打开「认证资料」，发送身份证照片（或企业的营业执照/税号）。证件保持私密；管理员会通过通知回复。"],
  ["O que é o «Pagamento protegido»?", "What is «Protected payment»?", "什么是「保障支付」？"],
  ["Nas compras da Loja, pode pagar ao Huambo Online em vez de pagar ao vendedor. Guardamos o dinheiro e o vendedor só o recebe depois de confirmar que recebeu a encomenda. Se houver problema, peça reembolso em «Encomendas»: o dinheiro fica congelado até se resolver. Se não confirmar nem reclamar uns dias depois da entrega, o pagamento vai para o vendedor.", "For Shop purchases, you can pay Huambo Online instead of paying the seller. We hold the money and the seller only gets it after you confirm you received the order. If there's a problem, ask for a refund in «Orders»: the money stays frozen until it's resolved. If you neither confirm nor complain within a few days of delivery, the payment goes to the seller.", "在商店购物时，您可以向 Huambo Online 付款，而不是直接付给卖家。我们托管款项，您确认收到订单后卖家才能收款。如有问题，请在「订单」中申请退款：款项将被冻结直至解决。如送达后数日内既未确认也未投诉，款项将交给卖家。"],
  ["Vendo na Loja: como recebo o dinheiro do pagamento protegido?", "I sell in the Shop: how do I get protected payment money?", "我在商店出售：如何收到保障支付的款项？"],
  ["Espere pelo aviso «Pagamento recebido» antes de enviar. Depois de entregar, marque a encomenda como «Entregue». Quando o cliente confirmar (ou passar o prazo sem reclamação), o dinheiro passa para «A sua conta» → «O meu saldo». Indique o seu IBAN ou número Multicaixa Express e carregue em «Pedir levantamento».", "Wait for the «Payment received» notice before shipping. After delivering, mark the order as «Delivered». When the customer confirms (or the period passes with no complaint), the money moves to «Your account» → «My balance». Enter your IBAN or Multicaixa Express number and tap «Request withdrawal».", "收到「已收到付款」通知后再发货。送达后，将订单标记为「已送达」。客户确认后（或期限内无投诉），款项会转入「您的账户」→「我的余额」。填写您的 IBAN 或 Multicaixa Express 号码，然后点击「申请提现」。"],
  ["Como partilho um anúncio no WhatsApp?", "How do I share a listing on WhatsApp?", "如何在 WhatsApp 上分享信息？"],
  ["Abra o anúncio ou o produto e carregue em «📲 Partilhar no WhatsApp». A mensagem leva o título, o preço, o número do anúncio (ex.: A-1023) e a ligação, e no WhatsApp aparece a fotografia. Escolha o contacto ou o grupo.", "Open the listing or product and tap «📲 Share on WhatsApp». The message includes the title, price, listing number (e.g. A-1023) and link, and the photo appears in WhatsApp. Choose the contact or group.", "打开信息或商品并点击「📲 分享到 WhatsApp」。消息包含标题、价格、信息编号（例如：A-1023）和链接，WhatsApp 中会显示照片。选择联系人或群组即可。"],
  ["Os compradores podem ver o meu WhatsApp?", "Can buyers see my WhatsApp?", "买家能看到我的 WhatsApp 吗？"],
  ["Para proteger a sua privacidade, o seu número não é mostrado aos compradores: falam consigo pelas Mensagens do Huambo Online. Se guardar o seu WhatsApp em «A sua conta» → «WhatsApp», só a equipa do Huambo Online o vê.", "To protect your privacy, your number is not shown to buyers: they contact you through Huambo Online Messages. If you save your WhatsApp in “Your account” → “WhatsApp”, only the Huambo Online team can see it.", "为保护您的隐私，您的号码不会向买家显示：他们通过 Huambo Online 站内消息与您联系。如果您在“您的账户”→“WhatsApp”中保存号码，只有 Huambo Online 团队能看到。"],
  ["Como funciona o «Convide um amigo»?", "How does «Invite a friend» work?", "「邀请好友」如何运作？"],
  ["Em «Conta» → «Convidar amigos» tem o seu código e a sua ligação. Quem criar conta com o seu convite (nos primeiros 14 dias) fica ligado a si. Quando essa pessoa pagar a primeira mensalidade (profissional, empresa ou loja), ganha 1 mês grátis na sua mensalidade. Se ainda não tiver mensalidade, o prémio fica guardado.", "In «Account» → «Invite friends» you have your code and your link. Anyone who creates an account with your invite (within the first 14 days) is linked to you. When that person pays their first monthly fee (professional, business or shop), you earn 1 free month on your monthly fee. If you don't have a monthly fee yet, the reward is kept for you.", "在「账户」→「邀请好友」中有您的邀请码和链接。使用您的邀请创建账户的人（在前14天内）会与您关联。当对方支付首月月费（专业人士、企业或商店）时，您的月费可获赠1个月免费。如果您尚未有月费，奖励会为您保留。"],
  ["O que é um agente no terreno?", "What is a field agent?", "什么是现场代理？"],
  ["É uma pessoa da praça (por exemplo, do Kapango) que ajuda os vendedores a pôr anúncios no Huambo Online. O anúncio fica sempre na conta do vendedor; ao publicar, o vendedor escreve o código do agente (ex.: AG1001). Quando esse anúncio é vendido, o agente ganha uma percentagem do valor da venda, que a administração confirma e que entra no saldo do agente. Para ser agente, abra «Conta» → «Ser agente».", "It's a person from the market (for example, Kapango) who helps sellers post listings on Huambo Online. The listing always stays in the seller's account; when publishing, the seller enters the agent's code (e.g. AG1001). When that listing is sold, the agent earns a percentage of the sale value, which the administration confirms and which goes into the agent's balance. To become an agent, open «Account» → «Become an agent».", "是市场中的人员（例如 Kapango 市场），帮助卖家在 Huambo Online 发布信息。信息始终在卖家的账户中；发布时，卖家填写代理编号（例如：AG1001）。该信息售出后，代理可获得成交金额的一定比例，经管理员确认后计入代理余额。如需成为代理，请打开「账户」→「成为代理」。"],
  ["E se o artigo não corresponder ao anúncio?", "What if the item doesn't match the listing?", "如果物品与信息不符怎么办？"],
  ["Todos os anúncios têm garantia de conformidade: quem publica declara que a descrição é verdadeira e completa, incluindo defeitos. Se o artigo que comprou ou arrendou tiver um defeito escondido ou for diferente, abra o anúncio e carregue em «O artigo não corresponde ao anúncio» (até 7 dias depois do negócio). Pode pedir troca, devolução e reembolso, ou reembolso. Se o dono recusar ou não responder em 3 dias, a administração decide. Nas compras da Loja, use «Devoluções e reembolsos» na encomenda.", "All listings have a conformity guarantee: whoever publishes declares that the description is true and complete, including defects. If the item you bought or rented has a hidden defect or is different, open the listing and tap «The item doesn't match the listing» (up to 7 days after the deal). You can ask for an exchange, return and refund, or refund. If the owner refuses or doesn't reply within 3 days, the administration decides. For Shop purchases, use «Returns and refunds» on the order.", "所有信息都有符合性保证：发布者声明描述真实、完整，包括缺陷。如果您购买或租用的物品有隐藏缺陷或与描述不符，请打开该信息并点击「物品与信息不符」（交易后7天内）。您可以申请换货、退货并退款或退款。如果物主拒绝或3天内未回复，由管理员裁决。商店购物请在订单中使用「退货和退款」。"],
  ["Como evito burlas?", "How do I avoid scams?", "如何防范诈骗？"],
  ["Encontre-se num lugar público e movimentado (veja «Pontos de encontro seguros» em «Segurança»), veja o artigo e pague na entrega, ou use o Pagamento protegido na Loja. Nunca pague adiantado nem dê códigos que recebe por SMS ou o PIN. Nas mensagens, o Huambo Online avisa quando alguém pede pagamento adiantado ou códigos. Se suspeitar, use «Bloquear» e «Denunciar».", "Meet in a busy public place (see «Safe meeting points» in «Safety»), see the item and pay on delivery, or use Protected payment in the Shop. Never pay in advance or give out codes you receive by SMS or your PIN. In messages, Huambo Online warns you when someone asks for advance payment or codes. If you're suspicious, use «Block» and «Report».", "在人多的公共场所见面（参见「安全」中的「安全见面地点」），看货后当面付款，或在商店使用保障支付。切勿预付款，也不要透露短信验证码或 PIN。在消息中，如有人要求预付款或验证码，Huambo Online 会提醒您。如有怀疑，请使用「屏蔽」和「举报」。"],
  ["Como peço uma devolução ou reembolso?", "How do I request a return or refund?", "如何申请退货或退款？"],
  ["Em «Encomendas», escolha a encomenda e carregue em «Pedir devolução ou reembolso» (até 14 dias depois da entrega). Explique o problema e junte fotografias. Se o vendedor recusar ou não responder, pode chamar a administração. Veja «Devoluções e reembolsos».", "In «Orders», choose the order and tap «Request return or refund» (up to 14 days after delivery). Explain the problem and add photos. If the seller declines or doesn't reply, you can call in the administration. See «Returns and refunds».", "在「订单」中选择订单并点击「申请退货或退款」（送达后14天内）。说明问题并添加照片。如果卖家拒绝或未回复，您可以请管理员介入。参见「退货和退款」。"],
  ["Como gasto menos dados (saldo)?", "How do I use less data?", "如何节省流量？"],
  ["Ligue «📉 Poupar dados» no topo do Site, na página inicial da APP ou em «A sua conta». As fotografias das listas deixam de carregar (aparece um ícone) e, nos anúncios, só carregam quando tocar em «Ver as fotografias». Os vídeos só carregam quando carregar em ▶. No Site, «Automático» liga sozinho quando o telemóvel está em poupança de dados.", "Switch on «📉 Data saver» at the top of the website, on the app's home page or in «Your account». Photos in lists stop loading (an icon appears) and, on listings, they only load when you tap «See the photos». Videos only load when you tap ▶. On the website, «Automatic» switches on by itself when your phone is in data-saving mode.", "在网站顶部、应用首页或「您的账户」中打开「📉 节省流量」。列表中的照片将不再加载（显示为图标），信息中的照片只有在点击「查看照片」时才加载。视频只有在点击 ▶ 时才加载。在网站上，「自动」会在手机处于省流模式时自动开启。"],
  ["Posso usar sem internet?", "Can I use it without internet?", "没有网络可以使用吗？"],
  ["Pode ver a página inicial, a última pesquisa e os últimos anúncios que abriu. Para publicar, enviar mensagens ou propostas precisa de ligação.", "You can see the home page, your last search and the last listings you opened. To publish, send messages or offers you need a connection.", "您可以查看首页、最近一次搜索和最近打开的信息。发布、发送消息或报价需要联网。"],
  ["Como apago a minha conta?", "How do I delete my account?", "如何删除我的账户？"],
  ["Em «A sua conta», no fim da página, escreva ELIMINAR e confirme. Veja os pormenores em «Como apagar a minha conta».", "In «Your account», at the bottom of the page, type ELIMINAR and confirm. See the details in «How to delete my account».", "在「您的账户」页面底部输入 ELIMINAR 并确认。详情参见「如何删除我的账户」。"]
];
